import Service from "#class/service";
import readBuffer from "#helpers/readBuffer";
import { vindWerkbak } from "#helpers/werkbakken";
import type { ChangeToken, CommunicatieAanmaakOpties, CommunicatieId, CommunicatieReplyOpties, KoppelCommunicatieBody, OngekoppeldeCommunicatie, OngekoppeldeCommunicatieBijlage, OngekoppeldeInkComDetails, PolisId, PostResponse, RowRes, WerkbakId, WerkbakNaam } from "#types";

export interface Communicatie {
    externalIdentifier: CommunicatieId,
    changeToken: ChangeToken,
}

/** Gedeelde basis voor beide subservices. */
class CommunicatieSubService extends Service {

    /**
     * Maakt een methode van een url: vervangt `_id` door het communicatienummer
     * en stuurt een PUT met de changeToken.
     *
     * Alleen voor acties zonder extra parameters — heeft de call queryparams
     * nodig, schrijf dan gewoon een normale methode.
     * 
     * @param url De url met `_id` erin, bv. `unlinked-communication/_id/mark-as-done`
     * @returns Een functie die een Communicatie neemt en de PUT uitvoert.
     */
    protected comFunc(prefix: string, action: string) {
        return (com: Communicatie) =>
            this.session.putAxon(`${prefix}-communications/${com.externalIdentifier}/${action}`, com.changeToken);
    }
}

/**
 * Communicatie die (nog) niet aan een polis hangt.
 * Endpoints: `unlinked-communication/*` en `incoming-communication/*`.
 */
class OngekoppeldeCommunicatieService extends CommunicatieSubService {

    /** Meldt de communicatie gereed. */
    meldGereed = this.comFunc("unlinked", "mark-as-done");

    /** Annuleert de communicatie. */
    annuleer = this.comFunc("incoming", "cancel");

    /** Kent de communicatie toe aan gebruiker (zelf). */
    toekennenAanMijzelf(com: Communicatie, onOpening?: boolean) {
        return this.session.putAxon(
            `incoming-communication/${com.externalIdentifier}/assign-to-self`,
            com.changeToken,
            { onOpening }
        );
    }

    toekennenAanWerkbak(com: Communicatie, werkbak: WerkbakId) {
        return this.session.postAxon(
            `unlinked-communication/assign-unlinked-communications-to-inbox`,
            { body: [{ externalIdentifier: com.externalIdentifier, changeToken: com.changeToken }] },
            { inboxForCommunicationExtId: werkbak }
        );
    }

    /** Koppelt inkomende communicatie aan polis. */
    async koppel(com: Communicatie, polisnummer: PolisId, omschrijving: string, geefVrijNaKoppelen: boolean = true, werkbakNaam?: WerkbakNaam) {
        const url = `policy-communications/${com.externalIdentifier}/link-communication/policy/${polisnummer}`;
        const body: KoppelCommunicatieBody = {
            "communicationDescription": omschrijving,
            "changeToken": com.changeToken,

            // "General" als algemeen, "attachmentsForPolicy" als bijlagen voor polis
            "communicationDescriptionExtId": "General",

            // Geef vrij
            "releaseCommunication": geefVrijNaKoppelen,

            // Binnenkomend of uitgaand
            // "isIncoming": true,
            ...(typeof werkbakNaam === "string" ? { "selectedInboxRef": vindWerkbak(werkbakNaam) } : {}),
        };

        return this.session.postAxon<PostResponse>(url, { body });
    }

    /** Haalt de eigen ongekoppelde bak op. */
    getBak(werkbak?: string, oldFirst: boolean = true) {
        const query = {
            communicationStatusExtId: "Read",
            communicationShowOption: "MY_COMMUNICATIONS",
            communicationDirection: "INCOMING",
            assignedUserExtId: this.session.userId!,
            showOldCommunicationsFirst: String(oldFirst),
            showAllLanguages: "false",
            ...(werkbak ? { inboxForCommunicationExtId: werkbak } : {})
        };
        return this.session.getAxon<RowRes<OngekoppeldeCommunicatie>>(
            `unlinked-communication/search/overview`,
            query
        ).then(r => r.rows);
    }

    /** Beantwoordt een ongekoppelde inkomende mail. */
    async respond(options: CommunicatieReplyOpties) {
        const startUpData = await this.session.postAxon<any>(`unlinked-communication/read-start-up-communication-wizard-data?communicationExtId=${options.comId}&wizardMode=reply`);
        const tpl = startUpData.templateCommunication;

        const emailMessageBody =
            options.inhoud +
            `Van: ${tpl.emailAddressFrom}<br/>` +
            `Verzonden: ${tpl.dateReceived}<br/>` +
            `Onderwerp: ${tpl.emailSubject}<br/><br/>` +
            tpl.emailMessageBody;

        const body = {
            // ─── Koppeling aan de originele mail (uit startUpData) ───
            mode: "reply",
            oldCommunicationExtId: tpl.externalIdentifier,
            oldCommunicationChangeToken: tpl.changeToken,
            oldCommunicationCommTypeExtId: "Email",
            isOriginalCommunicationIncoming: true,

            // ─── Standaard lege documenten/bijlagen ───
            addNewDocumentsValueObject: { selectedCommunicationDocuments: [] },
            communicationCopyReceivers: [],
            preselectedDocumentCategories: [],
            isLinkedToFinancialTransfer: false,
            isLinkedFinancialTransferFinished: false,

            communication: {
                // ─── Overgenomen uit de originele mail ───
                changeToken: tpl.changeToken,
                externalIdentifier: tpl.externalIdentifier,
                tsCommunicationCreated: tpl.tsCommunicationCreated,
                dateReceived: tpl.dateReceived,
                description: tpl.description,
                communicationDescriptionExtId: tpl.communicationDescriptionExtId,
                communicationDescriptionName: tpl.communicationDescriptionName,
                inboxForCommunicationExtId: tpl.inboxForCommunicationExtId,
                outputLabelDomainForSenderEmailAddress: tpl.outputLabelDomainForSenderEmailAddress,
                outputLabelAliasForSenderEmailAddress: tpl.outputLabelAliasForSenderEmailAddress,

                // ─── Inhoud van de reply ───
                emailSubject: `${options.onderwerp} (RE: ${tpl.emailSubject})`,
                emailMessageBody,

                // ─── Adressering: wij (a.s.r.) → oorspronkelijke afzender ───
                emailAddressFrom: options.verzenderAdres, // bv. "LK4669_OTA@asr.nl"
                emailAddressFromAlias: options.verzenderAlias,
                emailAddressTo: tpl.emailAddressFrom, // afzender wordt ontvanger

                // ─── Richting: Company → Customer ───
                communicationOriginRef: { externalIdentifier: "Company", entity: {} },
                communicationDestinationRef: { externalIdentifier: "Customer", entity: { externalIdentifier: "Company", name: "Maatschappij" } },
                communicationRoutingRef: { externalIdentifier: "DirectlyToCustomer", entity: {} },

                // ─── Vaste refs (bevestigd door startUpData) ───
                outputLabelRef: startUpData.outputLabelRef,
                communicationTypeRef: { externalIdentifier: "Email", entity: { externalIdentifier: "Email", name: "E-mail" } },
                communicationStatusRef: { externalIdentifier: "Read", entity: { externalIdentifier: "Read", name: "Ingelezen" } },
                emailContentTypeRef: { externalIdentifier: "html", entity: { externalIdentifier: "html" } },
                languageRef: { externalIdentifier: "NL", language: {} },
                printLocationRef: { externalIdentifier: "ViaPrintQueue", entity: { externalIdentifier: "ViaPrintQueue" } },
                printDestinationRef: { externalIdentifier: "SystemDefault", entity: { externalIdentifier: "SystemDefault" } },
                printLocally: true,

                // ─── Vaste vlaggen ───
                contactRegistration: false,
                containsPrivateInformation: false,
                containsMedicalInformation: false,
                isLegalAid: false,
                isFeedback: false,
                sendAsRegistered: false,
                addAddressDocument: false,
                markAsNotSend: false,
                isCopy: false,
                isIncoming: true,
                hasPriority: false,
                hasMarking: false,
                needsExtCustFeedbackRequest: false,
                isContentExternallyManaged: false,
                isLinkedToPeriodicPayment: false,
                isForContactRegistration: false,

                // ─── Lege refs (verplicht in het schema) ───
                enclosures: [],
                logonUserRef: {},
                markedAsDoneLogonUserRef: {},
                assessmentRef: { entity: {} },
                communicationRoleRef: { entity: {} },
                communicationReasonRef: { entity: {} },
                communicationSubReasonRef: { entity: {} },
                communicationQuestionRef: { entity: {} },
                coveringLetterRef: { entity: {} },
                groupCodeForReportingComRef: { entity: {} },
                caseProcessGroupLogonUserCodeRef: { entity: {} },
                printQueueRef: { entity: {} },
                communicationCopyReceiverList: [],
                entityExtIds: {},
            },

            // ─── Documenttype + afhandeling ───
            selectedEnclosures: [],
            // documentTypeForEmailRef: {
            //     externalIdentifier: "schade_algemeen_handmatige_brief_niet_gekoppelde_communicatie",
            //     entity: {
            //         externalIdentifier: "schade_algemeen_handmatige_brief_niet_gekoppelde_communicatie",
            //         name: "ALG - Handmatige brief niet-gekoppelde communicatie",
            //     },
            // },
            markAsDone: false, // !
        };

        return this.session.postAxon<PostResponse<CommunicatieId>>("unlinked-communication/save", { body });
    }
}

/**
 * Communicatie die aan een polis hangt.
 * Endpoints: `policy-communications/*`.
 */
class GekoppeldeCommunicatieService extends CommunicatieSubService {

    /** Meldt de communicatie gereed. */
    meldGereed = this.comFunc("policy", "mark-as-done");

    /** Zet de communicatie vanaf 'gereed' terug naar 'in behandeling'. */
    zetInBehandeling = this.comFunc("policy", "reopen");

    /** Ontkoppelt de communicatie van de polis. */
    loskoppelen = this.comFunc("policy", "unlink");

    /** Geeft de communicatie vrij. */
    geefVrij = this.comFunc("policy", "release");

    /** Verwijdert de communicatie. */
    verwijder = this.comFunc("policy", "delete");

    toekennenAanWerkbak(com: Communicatie, werkbak: WerkbakId) {
        return this.session.putAxon(
            `policy-communications/${com.externalIdentifier}/assign-to-inbox`,
            com.changeToken,
            { inboxForCommunicationExtId: werkbak }
        );
    }
}

/**
 * Entrypoint: `session.communicaties`.
 * Bevat alles wat voor beide soorten communicatie werkt;
 * de rest zit in `.ongekoppeld` en `.gekoppeld`.
 */
export default class CommunicatieService extends Service {

    readonly ongekoppeld = new OngekoppeldeCommunicatieService(this.session);
    readonly gekoppeld = new GekoppeldeCommunicatieService(this.session);

    /** Maakt een nieuwe uitgaande mail aan op een polis. */
    async create(options: CommunicatieAanmaakOpties, meldGereed = false) {

        const { bericht } = options;
        const body = {
            "mode": "add",
            "addNewDocumentsValueObject": {
                "selectedCommunicationDocuments": [],
                "sendByDefConcisePackPolSched": true
            },

            // CC-ontvangers
            "communicationCopyReceivers": [],

            // Polis en polisversie (vereist)
            "entityExtIds": {
                "policyExtId": options.polisnummer,
                "policyVersionExtId": options.actueleVersieId
            },
            "communication": {
                "enclosures": [],

                "emailMessageBody": bericht.inhoud,
                "emailSubject": bericht.onderwerp,
                "emailAddressFrom": bericht.verzenderAdres,
                "emailAddressFromAlias": bericht.verzenderAlias,
                "emailAddressTo": bericht.ontvangerAdres,

                "communicationOriginRef": { "externalIdentifier": "Company", "entity": {} },
                "communicationDestinationRef": { "externalIdentifier": "Intermediary" },

                // Label (pagina 1)
                "outputLabelRef": {
                    "externalIdentifier": "ASRZ",
                    "entity": {
                        "externalIdentifier": "ASRZ",
                        "name": "a.s.r. zakelijk"
                    }
                },
                "intermediaryExternalIdentifier": options.tussenpersoonId,
                "communicationTypeRef": { "externalIdentifier": "Email" },

                // CC (deel 2)?
                "communicationCopyReceiverList": [],
                "languageRef": { "externalIdentifier": "NL" },
            },

            // Gereedmelden?
            "markAsDone": meldGereed,
        } as const;

        return this.session.postAxon<PostResponse<CommunicatieId>>(
            `policy-communications/save`,
            body,
            { policyCommunicationTypeExtId: "PolicyVersion" },
            // { mode: "cors", credentials: "include" }
        );
    }

    /** Fetcht de bijlagen van een communicatie, ongeacht of die gekoppeld is */
    vindBijlagen(com: Communicatie) {
        return this.session.getAxon<RowRes<OngekoppeldeCommunicatieBijlage>>(
            `communication-documents/search-by-communication/overview`,
            { communicationExtId: com.externalIdentifier }
        ).then(r => r.rows);
    }

    /** Vind informatie die inhoudelijk over een specifieke communicatie gaat */
    vindDetails = (comId: CommunicatieId, isOngekoppeld: boolean) =>
        this.session.getAxon<OngekoppeldeInkComDetails>(
            `communications/${comId}/detail`,
            // ? Niet noodzakelijk
            { isForUncoupledCommunication: isOngekoppeld },
        );

    downloadBijlagen = (comId: CommunicatieId, savePath: string) =>
        this.session.getAxonRaw(`communication-documents/export-documents-as-zip?communicationExtId=${comId}&clientIdentifier=${this.session._clientId}`) // { headers: { Accept: "*/*", } }
            .then(res => readBuffer(res, savePath));
}